def single_xor(a: list[int]) -> int:
    x = 0
    for v in a:
        x ^= v
    return x

def single_non_duplicate(a: list[int]) -> int:
    lo, hi = 0, len(a) - 1
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if mid % 2 == 1:
            mid -= 1
        if a[mid] == a[mid + 1]:
            lo = mid + 2
        else:
            hi = mid
    return a[lo]
